                if (n0 < N) { float v = Activate(c222 + bias0, act); if (hasRes != 0) v += res[(long)m1 * N + n0]; C[(long)m1 * N + n0] = v; }
                if (n1 < N) { float v = Activate(c223 + bias1, act); if (hasRes != 0) v += res[(long)m1 * N + n1]; C[(long)m1 * N + n1] = v; }
