    {
        int numTilesM = (M + 255) / 256;
        int tileRow = Grid.IdxX % numTilesM;
        int tileCol = Grid.IdxX / numTilesM;
        int tid = Group.IdxX;
        int warp = tid >> 5, lane = tid & 31;
        int g = lane >> 2, t = lane & 3;
        int wm = warp >> 1, wn = warp & 1;
        float inv = sc[1];
        var aS = SharedMemory.Allocate<uint>(2 * 256 * 16);
        var bS = SharedMemory.Allocate<uint>(2 * 128 * 16);
        float c000 = 0f, c001 = 0f, c002 = 0f, c003 = 0f;
