        int sOff0 = (cr + 0) * 16 + ((cc ^ (((cr + 0) >> 1) & 3)) << 2);
        int aR1 = tileRow * BMS + cr + 32, bR1 = tileCol * BN + cr + 32;
        int aSz1 = aR1 < M ? 16 : 0, bSz1 = bR1 < N ? 16 : 0;
